// Ordinary Store frame echoes, separate from title and cell printing.
// Fixed affine contours use nested white coverage and one color application.
// Widths descend through a Gaussian-convolved narrow stroke at alpha steps
// of at most 1/255; conditional opacity preserves the previous coverage.
// The fourth-card ramp supplies a finite end independently of stroke caps.
// These primitives live in the cached shelf material, not per-frame effects.
// Source hypothesis, derivation and residuals: docs/neomil/store-frame-echo.md.
const fn frame_echo_bands<const N: usize>(x:f32,y:f32,segs:&'static [Seg],close:bool,
        widths:&[f32;N], opacities:&[f32;N]) -> [Prim;N] {
    let mut out=[Prim::Path{x:0.0,y:0.0,segs:&[],close:false,fill:None,stroke:None,width:0.0};N];
    let mut i=0; while i<N {
        out[i]=Prim::Path{x,y,segs,close,fill:None,stroke:Some(Ink::Fixed(
            iced::Color{r:1.0,g:1.0,b:1.0,a:opacities[i]})),width:widths[i]};
        i+=1;
    } out
}
